"""Systems Mastery S09: the debugging method."""
import sysviz as v

FIRST5_VIZ = v.figure(
    720, 150,
    [v.box(10, 20, 125, 52, "What changed?", "acc", "deploy, config, load"),
     v.arrow(135, 46, 165, 46), v.box(165, 20, 125, 52, "Who is hit?", "acc", "all, some, one"),
     v.arrow(290, 46, 320, 46), v.box(320, 20, 125, 52, "Reproduce", "acc", "smallest case"),
     v.arrow(445, 46, 475, 46), v.box(475, 20, 125, 52, "Narrow", "acc", "halve the space"),
     v.arrow(600, 46, 625, 46), v.box(625, 20, 85, 52, "Fix", "ok"),
     v.text(360, 110, "If users are hurting now, roll back or mitigate first, then find the cause.", "dg-s"),
     v.text(360, 130, "Stopping the damage and understanding it are two separate jobs.", "dg-s")],
    "The first five minutes", "A calm order of questions beats random poking")

